package main

import (
	"encoding/json"
	"net/http"
	"strings"

	"github.com/router-for-me/CLIProxyAPI/v7/sdk/pluginapi"
)

func (r *pluginRuntime) dashboardResponse(request pluginapi.ManagementRequest) pluginapi.ManagementResponse {
	r.mu.RLock()
	configured := r.config.Language
	r.mu.RUnlock()
	queryLang := ""
	if request.Query != nil {
		queryLang = request.Query.Get("lang")
	}
	lang := languageFromHTTP(configured, request.Headers, request.Query)
	preferred := languagePreference(configured, queryLang)
	body := renderDashboardHTML(preferred, lang)
	return pluginapi.ManagementResponse{
		StatusCode: http.StatusOK,
		Headers: http.Header{
			"Content-Type":           []string{"text/html; charset=utf-8"},
			"Cache-Control":          []string{"no-store"},
			"X-Content-Type-Options": []string{"nosniff"},
			"Referrer-Policy":        []string{"no-referrer"},
			"Content-Language":       []string{localeTag(lang)},
			"Content-Security-Policy": []string{
				"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src data: blob:; base-uri 'none'; form-action 'none'; frame-ancestors 'self'",
			},
		},
		Body: []byte(body),
	}
}

func dashboardResponse() pluginapi.ManagementResponse {
	return (&pluginRuntime{}).dashboardResponse(pluginapi.ManagementRequest{})
}

func renderDashboardHTML(preferred Language, lang Language) string {
	if preferred == "" {
		preferred = LanguageAuto
	}
	lang = effectiveLanguage(lang)
	if preferred != LanguageAuto {
		preferred = effectiveLanguage(preferred)
	}
	catalogs, err := catalogJSON()
	if err != nil {
		catalogs = []byte(`{"en":{}}`)
	}
	bootstrap, err := json.Marshal(map[string]any{
		"lang":      string(lang),
		"locale":    localeTag(lang),
		"preferred": string(preferred),
		"catalogs":  json.RawMessage(catalogs),
	})
	if err != nil {
		bootstrap = []byte(`{"lang":"en","preferred":"auto","catalogs":{"en":{}}}`)
	}
	html := dashboardHTMLTemplate
	html = strings.ReplaceAll(html, "__I18N_BOOTSTRAP__", string(bootstrap))
	html = strings.ReplaceAll(html, "__LANG_TAG__", localeTag(lang))
	html = strings.ReplaceAll(html, "__LANGUAGE_OPTIONS__", languageOptionsHTML(lang, preferred))
	for key := range messages[LanguageEnglish] {
		html = strings.ReplaceAll(html, "__MSG_"+key+"__", T(lang, key))
	}
	return html
}

